CREATE OR REPLACE FUNCTION private.dic_admin_account_delete_prepare(p_operation_id uuid, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare op private.dic_admin_account_delete_operations; ids uuid[]; actual jsonb; storage_blocked boolean:=false;
begin
 select * into op from private.dic_admin_account_delete_operations
 where id=p_operation_id for update;
 if not found or op.actor_id is distinct from p_actor_id then
  raise exception using errcode='42501',message='Deletion operation unavailable.';
 end if;
 if op.phase='completed' then return jsonb_build_object('ok',true,'completed',true); end if;
 if not exists(select 1 from private.app_admins where owner_id=p_actor_id)
    or not exists(select 1 from private.beta_members
       where owner_id=p_actor_id and enabled and admitted_at is not null) then
  raise exception using errcode='42501',message='Administrator no longer admitted.';
 end if;
 if exists(select 1 from private.app_admins where owner_id=op.target_id)
    or op.target_id=p_actor_id then
  raise exception using errcode='42501',message='Administrator accounts are protected.';
 end if;
 if op.phase='requested' then
  if not exists(select 1 from auth.users where id=op.target_id) then
   raise exception using errcode='23514',message='Target account is missing before preparation.';
  end if;
  -- Recheck the same preview under the service-side record lock.
  -- No JWT actor impersonation or unsafe service-role bypass of an admin check.
  actual:=private.dic_admin_account_delete_impact(op.target_id);
  if actual is distinct from op.expected_impact then
   raise exception using errcode='PT409',message='Account changed after confirmation.';
  end if;
  select coalesce(array_agg(c.id order by c.id),'{}'::uuid[]) into ids
  from private.contributors c where c.owner_id=op.target_id;
  -- Supabase Auth deletion refuses users who own Storage objects. Fail before
  -- changing admission when the live provider exposes that table.
  if to_regclass('storage.objects') is not null then
   execute 'select exists(select 1 from storage.objects where owner=$1 or owner_id=$1::text)'
     into storage_blocked using op.target_id;
   if storage_blocked then
    raise exception using errcode='23514',message='Member has Storage-owned objects; review before deletion.';
   end if;
  end if;
  -- Prevent deletion of prior actor audit evidence if a formerly privileged user
  -- was subsequently demoted. Do not silently erase immutable admin audits.
  if exists(select 1 from private.admin_content_edits where actor_id=op.target_id) then
   raise exception using errcode='23514',message='Historical administrative actor audit requires separate review.';
  end if;
  update private.beta_members set enabled=false where owner_id=op.target_id;
  -- Eliminate restrictive user references; retain minimum action/timestamp audit.
  update private.admin_content_edits
     set subject_owner_id=null,before_values='{}'::jsonb,after_values='{}'::jsonb
     where subject_owner_id=op.target_id;
  delete from private.dic_source_attempts where owner_id=op.target_id;
  update private.import_control
     set owner_only_exception_owner_id=null,owner_only_exception_approved_at=null,
         owner_only_exception_expires_at=null
     where owner_only_exception_owner_id=op.target_id;
  update private.dic_admin_account_delete_operations
     set phase='prepared',contributor_ids=ids,prepared_at=now()
     where id=op.id;
  op.phase:='prepared';op.contributor_ids:=ids;
 end if;
 if op.phase='prepared' and exists(
  select 1 from private.beta_members where owner_id=op.target_id and enabled
 ) then
  raise exception using errcode='23514',message='Admission unexpectedly restored while deleting.';
 end if;
 return jsonb_build_object('ok',true,'target_id',op.target_id,'mode',op.community_mode,'phase',op.phase);
end $function$

CREATE OR REPLACE FUNCTION private.dic_admin_account_delete_preview(p_member_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();
begin
 perform private.require_member();
 if actor is null or not private.is_admin() then
  raise exception using errcode='42501',message='Administrator required.';
 end if;
 if p_member_id is null or p_member_id=actor or
    exists(select 1 from private.app_admins where owner_id=p_member_id) then
  raise exception using errcode='42501',message='Administrator accounts are protected.';
 end if;
 return private.dic_admin_account_delete_impact(p_member_id);
end $function$

CREATE OR REPLACE FUNCTION private.dic_admin_account_delete_request(p_member_id uuid, p_community_mode text, p_expected_impact jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); actual jsonb; prior private.dic_admin_account_delete_operations; opid uuid;
begin
 perform private.require_member();
 if actor is null or not private.is_admin() then
  raise exception using errcode='42501',message='Administrator required.';
 end if;
 if p_community_mode not in ('keep','remove') or p_community_mode is null
    or p_expected_impact is null or p_member_id is null then
  raise exception using errcode='22023',message='Invalid account deletion confirmation.';
 end if;
 if p_member_id=actor or exists(select 1 from private.app_admins where owner_id=p_member_id) then
  raise exception using errcode='42501',message='Administrator accounts are protected.';
 end if;
 select * into prior from private.dic_admin_account_delete_operations
 where target_id=p_member_id and phase<>'completed' for update;
 if found then
  if prior.actor_id is distinct from actor or prior.community_mode<>p_community_mode then
   raise exception using errcode='23514',message='Another deletion is already in progress.';
  end if;
  return jsonb_build_object('ok',true,'operation_id',prior.id,'phase',prior.phase,'retry',true);
 end if;
 perform 1 from auth.users where id=p_member_id for update;
 actual:=private.dic_admin_account_delete_preview(p_member_id);
 if actual is distinct from p_expected_impact then
  raise exception using errcode='PT409',message='Account records changed. Review deletion impact again.';
 end if;
 insert into private.dic_admin_account_delete_operations(actor_id,target_id,community_mode,expected_impact)
 values(actor,p_member_id,p_community_mode,actual) returning id into opid;
 return jsonb_build_object('ok',true,'operation_id',opid,'phase','requested');
end $function$

CREATE OR REPLACE FUNCTION private.dic_admin_review_signup(p_member_id uuid, p_action text, p_expected_state text DEFAULT 'pending'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); member private.beta_members; verified boolean;
begin
 perform private.require_member();
 if actor is null or not private.is_admin() then
  raise exception using errcode='42501',message='Administrator required.';
 end if;
 if p_member_id is null or p_member_id=actor or p_action is null or p_action not in ('approve','reject')
  or p_expected_state is distinct from 'pending' then
  raise exception using errcode='22023',message='Invalid signup review.';
 end if;
 if exists(select 1 from private.app_admins where owner_id=p_member_id) then
  raise exception using errcode='42501',message='Administrator protected.';
 end if;
 select * into member from private.beta_members where owner_id=p_member_id for update;
 if not found then
  raise exception using errcode='22023',message='Account unavailable.';
 end if;
 -- A repeat click or concurrent reviewer must be safely rejected as stale.
 if member.signup_review_state <> p_expected_state or
    member.admitted_at is not null or member.enabled then
  return jsonb_build_object('ok',false,'code','stale_review');
 end if;
 select u.email_confirmed_at is not null into verified
 from auth.users u where u.id=p_member_id;
 if p_action='approve' and verified is distinct from true then
  return jsonb_build_object('ok',false,'code','verify_email_first');
 end if;
 update private.beta_members set
   signup_review_state=case when p_action='approve' then 'approved' else 'rejected' end,
   enabled=(p_action='approve'),
   admitted_at=case when p_action='approve' then now() else null end
 where owner_id=p_member_id;
 insert into private.dic_signup_review_events(member_id,actor_id,action,previous_state)
 values(p_member_id,actor,p_action,member.signup_review_state);
 return jsonb_build_object('ok',true,'decision',p_action,'member_id',p_member_id);
end $function$

CREATE OR REPLACE FUNCTION private.dic_admin_set_member_access(p_member_id uuid, p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();m private.beta_members;found_member uuid;
begin
 if actor is null or not private.is_admin() then
  raise exception using errcode='42501',message='Administrator access required.';
 end if;
 if p_member_id is null or p_enabled is null then
  raise exception using errcode='22023',message='Member and desired access are required.';
 end if;
 -- Never allow an administrator to revoke themself OR ANY administrator.
 -- The underlying permanent admin role has no expiration.
 if p_member_id=actor or exists(select 1 from private.app_admins where owner_id=p_member_id) then
  raise exception using errcode='42501',message='Administrator accounts cannot be removed here.';
 end if;
 -- Permanently deleting a member supersedes reversible Restore/Remove.
 if exists(select 1 from private.dic_admin_account_delete_operations
   where target_id=p_member_id and phase<>'completed') then
  raise exception using errcode='23514',message='Permanent deletion is underway; finish it before changing access.';
 end if;
 select * into m from private.beta_members where owner_id=p_member_id for update;
 if not found or m.admitted_at is null then
  raise exception using errcode='22023',message='Only previously admitted members can be changed.';
 end if;
 if p_enabled and not exists(select 1 from auth.users where id=p_member_id and email_confirmed_at is not null) then
  raise exception using errcode='42501',message='Verified email required.';
 end if;
 if m.enabled=p_enabled then
  return jsonb_build_object('ok',true,'enabled',p_enabled,'unchanged',true);
 end if;
 update private.beta_members set enabled=p_enabled
 where owner_id=p_member_id returning owner_id into found_member;
 insert into private.admin_access_events(actor_id,action,member_id)
 values(actor,case when p_enabled then 'restore_access' else 'remove_access' end,found_member);
 -- No auth.users deletion, note deletion, contribution identity reidentification,
 -- historical mutation, or implicit sign-out of already issued Supabase tokens.
 -- All member RPCs and RLS must recheck private.is_member().
 return jsonb_build_object('ok',true,'enabled',p_enabled);
end $function$

CREATE OR REPLACE FUNCTION private.dic_admin_signup_requests(p_offset integer DEFAULT 0, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare total bigint; listing jsonb;
begin
 perform private.require_member();
 if auth.uid() is null or not private.is_admin() then
  raise exception using errcode='42501', message='Administrator required.';
 end if;
 if p_offset is null or p_offset<0 or p_offset>1000000
    or p_limit is null or p_limit<1 or p_limit>50 then
  raise exception using errcode='22023',message='Invalid paging.';
 end if;
 select count(*) into total from private.beta_members m
 where m.admitted_at is null and m.signup_review_state='pending';
 select coalesce(jsonb_agg(v.record order by v.created_at,v.id),'[]'::jsonb) into listing
 from (select m.owner_id as id,u.created_at,
   jsonb_build_object(
    'id',m.owner_id,'email',left(coalesce(u.email,''),254),
    'created_at',u.created_at,'email_verified',u.email_confirmed_at is not null,
    'review_state',m.signup_review_state
   ) as record
   from private.beta_members m join auth.users u on u.id=m.owner_id
   where m.admitted_at is null and m.signup_review_state='pending'
   order by u.created_at,m.owner_id limit p_limit offset p_offset) v;
 return jsonb_build_object('total',total,'offset',p_offset,'items',coalesce(listing,'[]'::jsonb));
end $function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
  tbl name;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        SELECT c.relname INTO tbl FROM pg_catalog.pg_class c WHERE c.oid = cmd.objid;
        EXECUTE format('alter table if exists %I.%I enable row level security', cmd.schema_name, tbl);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
